CREATE TABLE IF NOT EXISTS schema_version(version integer PRIMARY KEY);
INSERT INTO schema_version VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS admins(id integer PRIMARY KEY CHECK(id=1),username text UNIQUE NOT NULL,password_hash text NOT NULL,totp bytea,totp_step bigint NOT NULL DEFAULT -1);
CREATE TABLE IF NOT EXISTS recovery(hash text PRIMARY KEY,used boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS sessions(hash text PRIMARY KEY,created timestamptz NOT NULL DEFAULT now(),expires timestamptz NOT NULL,ip text NOT NULL,ua text NOT NULL);
CREATE TABLE IF NOT EXISTS challenges(hash text PRIMARY KEY,expires timestamptz NOT NULL,kind text NOT NULL,secret bytea,approved boolean NOT NULL DEFAULT false,ip text NOT NULL,ua text NOT NULL);
CREATE TABLE IF NOT EXISTS auth_failures(key text PRIMARY KEY,failures integer NOT NULL,until_time timestamptz NOT NULL,updated timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id bigserial PRIMARY KEY,at timestamptz NOT NULL DEFAULT now(),action text NOT NULL,target text NOT NULL DEFAULT '',result text NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id integer PRIMARY KEY CHECK(id=1),encrypted bytea NOT NULL);
CREATE TABLE IF NOT EXISTS enrollment(hash text PRIMARY KEY,expires timestamptz NOT NULL,name text NOT NULL,role text NOT NULL,auto_approve boolean NOT NULL DEFAULT false,consumed boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS nodes(id text PRIMARY KEY,name text NOT NULL,role text NOT NULL,pubkey bytea NOT NULL,approved boolean NOT NULL DEFAULT false,created timestamptz NOT NULL DEFAULT now(),seen timestamptz,telemetry jsonb,metadata jsonb NOT NULL DEFAULT '{}',reconnects integer NOT NULL DEFAULT 0);
ALTER TABLE nodes ADD COLUMN IF NOT EXISTS revision bigint NOT NULL DEFAULT 1;
INSERT INTO schema_version VALUES(2) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS measurements(id bigserial PRIMARY KEY,node_id text REFERENCES nodes(id) ON DELETE CASCADE,at timestamptz NOT NULL DEFAULT now(),data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS measurements_node_at ON measurements(node_id,at DESC);
CREATE INDEX IF NOT EXISTS measurements_at ON measurements(at);
CREATE TABLE IF NOT EXISTS measurement_rollups(node_id text REFERENCES nodes(id)ON DELETE CASCADE,at timestamptz,data jsonb NOT NULL,PRIMARY KEY(node_id,at));
CREATE TABLE IF NOT EXISTS node_usage(node_id text REFERENCES nodes(id) ON DELETE CASCADE,month text,rx bigint NOT NULL DEFAULT 0,tx bigint NOT NULL DEFAULT 0,started timestamptz NOT NULL,ended timestamptz NOT NULL,interface text NOT NULL,PRIMARY KEY(node_id,month));
ALTER TABLE nodes ADD COLUMN IF NOT EXISTS protocol integer NOT NULL DEFAULT 1;
ALTER TABLE nodes ADD COLUMN IF NOT EXISTS inventory jsonb NOT NULL DEFAULT '{}';
ALTER TABLE nodes ADD COLUMN IF NOT EXISTS inventory_at timestamptz;
CREATE TABLE IF NOT EXISTS tunnels(id text PRIMARY KEY,name text NOT NULL,revision bigint NOT NULL DEFAULT 1,cipher bytea NOT NULL,managed boolean NOT NULL DEFAULT false,desired text NOT NULL DEFAULT 'running',created timestamptz NOT NULL DEFAULT now(),updated timestamptz NOT NULL DEFAULT now(),health jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS tunnel_versions(tunnel_id text REFERENCES tunnels(id) ON DELETE CASCADE,revision bigint,cipher bytea NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tunnel_id,revision));
CREATE TABLE IF NOT EXISTS operations(id text PRIMARY KEY,request_key text UNIQUE NOT NULL,kind text NOT NULL,target text NOT NULL DEFAULT '',name text NOT NULL,phase text NOT NULL DEFAULT 'queued',cipher bytea NOT NULL,steps jsonb NOT NULL DEFAULT '[]',result jsonb NOT NULL DEFAULT '{}',error text NOT NULL DEFAULT '',deadline timestamptz,created timestamptz NOT NULL DEFAULT now(),updated timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS operations_pending ON operations(phase,created);
ALTER TABLE operations ADD COLUMN IF NOT EXISTS request_hash text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS commands(id text PRIMARY KEY,operation_id text REFERENCES operations(id),node_id text REFERENCES nodes(id) ON DELETE CASCADE,stage text NOT NULL,kind text NOT NULL,cipher bytea NOT NULL,state text NOT NULL DEFAULT 'queued',expires timestamptz NOT NULL,lease_until timestamptz,result_cipher bytea,created timestamptz NOT NULL DEFAULT now(),UNIQUE(operation_id,node_id,stage));
CREATE INDEX IF NOT EXISTS commands_pending ON commands(node_id,state,created);
CREATE TABLE IF NOT EXISTS port_reservations(plan_id text REFERENCES operations(id) ON DELETE CASCADE,node_id text REFERENCES nodes(id) ON DELETE CASCADE,host text NOT NULL,port integer NOT NULL,protocol text NOT NULL,expires timestamptz NOT NULL,PRIMARY KEY(plan_id,node_id,host,port,protocol));
CREATE INDEX IF NOT EXISTS port_reservations_lookup ON port_reservations(node_id,port,protocol);
CREATE TABLE IF NOT EXISTS certificates(id text PRIMARY KEY,name text NOT NULL,domain text NOT NULL,cipher bytea NOT NULL,revision bigint NOT NULL DEFAULT 1,not_after timestamptz NOT NULL,issuer text NOT NULL,method text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',updated timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS certificate_links(certificate_id text REFERENCES certificates(id) ON DELETE CASCADE,node_id text REFERENCES nodes(id) ON DELETE CASCADE,instance_id text NOT NULL,trust_only boolean NOT NULL,hash text NOT NULL DEFAULT '',PRIMARY KEY(certificate_id,node_id,instance_id));
CREATE TABLE IF NOT EXISTS alerts(id bigserial PRIMARY KEY,rule text NOT NULL,target text NOT NULL,severity text NOT NULL,code text NOT NULL,active boolean NOT NULL DEFAULT true,created timestamptz NOT NULL DEFAULT now(),updated timestamptz NOT NULL DEFAULT now(),notified timestamptz,acknowledged boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS alerts_active ON alerts(rule,target) WHERE active;
ALTER TABLE alerts ADD COLUMN IF NOT EXISTS suppressed_until timestamptz;
CREATE TABLE IF NOT EXISTS checks(id bigserial PRIMARY KEY,node_id text REFERENCES nodes(id) ON DELETE CASCADE,target text NOT NULL,kind text NOT NULL,at timestamptz NOT NULL DEFAULT now(),data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS checks_target ON checks(target,at DESC);
CREATE TABLE IF NOT EXISTS recovery_rules(node_id text REFERENCES nodes(id) ON DELETE CASCADE,instance_id text,policy jsonb NOT NULL,PRIMARY KEY(node_id,instance_id));
CREATE TABLE IF NOT EXISTS telegram_actions(hash text PRIMARY KEY,operation_id text REFERENCES operations(id),expires timestamptz NOT NULL,consumed boolean NOT NULL DEFAULT false);
INSERT INTO schema_version VALUES(4) ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS telegram_cursor(id integer PRIMARY KEY CHECK(id=1),offset_value bigint NOT NULL);
ALTER TABLE alerts ADD COLUMN IF NOT EXISTS notification_attempt timestamptz;
